from __future__ import annotations

@click.group()
def cli():
    """sllm-store CLI"""
    pass

@cli.command()
@click.option('--host', default='0.0.0.0', help='Host')
@click.option('--port', default=8073, help='Port')
@click.option('--storage-path', default=None, help='Storage path (default: $STORAGE_PATH or ~/models/)')
@click.option('--num-thread', default=4, help='Number of I/O threads')
@click.option('--chunk-size', default='32MB', help='Chunk size, e.g., 4KB, 1MB, 1GB')
@click.option('--mem-pool-size', default='4GB', help='Memory pool size, e.g., 1GB, 4GB, 1TB')
@click.option('--disk-size', default='128GB', help='Disk size, e.g., 1GB, 4GB, 1TB')
@click.option('--registration-required', default=False, help='Require registration before loading model')
def start(host, port, storage_path, num_thread, chunk_size, mem_pool_size, disk_size, registration_required):
    """Start the gRPC server."""
    storage_path = resolve_storage_path(storage_path)
    chunk_size = to_num_bytes(chunk_size)
    mem_pool_size = to_num_bytes(mem_pool_size)
    try:
        logger.info('Starting gRPC server')
        asyncio.run(serve(host=host, port=port, storage_path=storage_path, num_thread=num_thread, chunk_size=chunk_size, mem_pool_size=mem_pool_size, registration_required=registration_required))
    except KeyboardInterrupt:
        logging.info('Server stopped by user')
        sys.exit(0)

@cli.command()
@click.option('--model', 'model_name', type=str, required=True, help='Model name from HuggingFace model hub')
@click.option('--backend', type=str, required=True, help='Backend')
@click.option('--dtype', type=click.Choice(['auto', 'float16', 'bfloat16', 'float32']), default='float16', help='Model dtype for the vLLM backend')
@click.option('--trust-remote-code', is_flag=True, default=False, help='Trust model code for the vLLM backend')
@click.option('--mm-encoder-tp-mode', type=click.Choice(['weights', 'data']), default=None, help='Multimodal encoder TP mode for the vLLM backend')
@click.option('--adapter-name', type=str, help='Name of the LoRA adapter')
@click.option('--tensor-parallel-size', type=int, default=1, help='Tensor parallel size')
@click.option('--local-model-path', type=str, help='Local path to the model snapshot')
@click.option('--storage-path', default=None, help='Local path to save the model (default: $STORAGE_PATH or ~/models/)')
def save(model_name, backend, adapter_name, tensor_parallel_size, local_model_path, storage_path, dtype='float16', trust_remote_code=False, mm_encoder_tp_mode=None):
    """
    Saves a model to the sllm-store's storage.

    This command is for adding new models to the sllm-store's local storage.
    """
    storage_path = resolve_storage_path(storage_path)
    logger.info(f'Saving model {(adapter_name if adapter_name else model_name)} to {storage_path}')
    try:
        if backend == 'vllm':
            downloader = VllmModelDownloader()
            storage_path = os.path.join(storage_path, 'vllm')
            downloader.download_vllm_model(model_name, dtype, tensor_parallel_size=tensor_parallel_size, storage_path=storage_path, local_model_path=local_model_path, trust_remote_code=trust_remote_code, mm_encoder_tp_mode=mm_encoder_tp_mode)
        elif backend == 'transformers':
            from sllm_store.transformers import save_model, save_lora
            if adapter_name:
                from peft import PeftModel
                config = AutoConfig.from_pretrained(model_name, trust_remote_code=True)
                config.torch_dtype = torch.float16
                module = importlib.import_module('transformers')
                hf_model_cls = module.AutoModelForCausalLM
                base_model = hf_model_cls.from_config(config, trust_remote_code=True).to(config.torch_dtype)
                model = PeftModel.from_pretrained(base_model, adapter_name)
                model_path = os.path.join(storage_path, adapter_name)
                save_lora(model, model_path)
            else:
                model = AutoModelForCausalLM.from_pretrained(model_name, torch_dtype=torch.float16)
                model_path = os.path.join(storage_path, model_name)
                save_model(model, model_path)
        else:
            logger.error(f"Unsupported backend '{backend}'")
            sys.exit(1)
    except Exception as e:
        logger.error(f'Failed to save model {model_name}: {e}', exc_info=True)
        sys.exit(1)
    logger.info(f'Model {(adapter_name if adapter_name else model_name)} saved successfully to {storage_path}')

@cli.command()
@click.option('--model', 'model_name', type=str, required=True, help='Model name from HuggingFace model hub')
@click.option('--backend', type=str, required=True, help='Backend')
@click.option('--adapter-name', type=str, help='Name of the LoRA adapter')
@click.option('--precision', type=click.Choice(['int8', 'fp4', 'nf4']), help='Precision of quantized model.')
@click.option('--storage-path', type=str, default=None, help='Local path where model is saved (default: $STORAGE_PATH or ~/models/)')
def load(model_name, backend, adapter_name, precision, storage_path):
    """
    Loads a model from the sllm-store's storage.

    This command is for loading new models from the sllm-store's local storage.
    """
    storage_path = resolve_storage_path(storage_path)
    logger.info(f'Loading model {(adapter_name if adapter_name else model_name)} from {storage_path}')
    quantization_config = None
    if precision:
        if precision == 'int8':
            quantization_config = BitsAndBytesConfig(load_in_8bit=True)
        elif precision == 'fp4':
            quantization_config = BitsAndBytesConfig(load_in_4bit=True)
        elif precision == 'nf4':
            quantization_config = BitsAndBytesConfig(load_in_4bit=True, bnb_4bit_quant_type='nf4')
    try:
        start_load_time = time.time()
        if backend == 'vllm':
            from vllm import LLM
            model_full_path = os.path.join(storage_path, 'vllm', model_name)
            llm = LLM(model=model_full_path, load_format='serverless_llm', dtype='float16')
            logger.info(f'Model loading time: {time.time() - start_load_time:.2f}s')
            example_inferences('vllm', model=llm)
        elif backend == 'transformers':
            from sllm_store.transformers import load_model, load_lora
            num_gpus = torch.cuda.device_count()
            for i in range(num_gpus):
                torch.ones(1).to(f'cuda:{i}')
                torch.cuda.synchronize()
            if adapter_name:
                model = load_model(model_name, device_map='auto', torch_dtype=torch.float16, storage_path=storage_path, fully_parallel=True)
                model = load_lora(model, adapter_name, adapter_path=adapter_name, device_map='auto', storage_path=storage_path, torch_dtype=torch.float16)
            else:
                model = load_model(model_name, device_map='auto', torch_dtype=torch.float16, storage_path=storage_path, fully_parallel=True, quantization_config=quantization_config)
            logger.info(f'Model loading time: {time.time() - start_load_time:.2f}s')
            example_inferences('transformers', model=model, model_name=model_name, adapter_name=adapter_name)
        else:
            logger.error(f"Unsupported backend '{backend}'")
            sys.exit(1)
    except Exception as e:
        logger.error(f'Failed to load model or perform inference: {e}', exc_info=True)
        sys.exit(1)
    logger.info(f'Model {(adapter_name if adapter_name else model_name)} loaded successfully from {storage_path}')

def main():
    cli()

